import { test, expect, Page } from '@playwright/test';

test.describe('Background Sync Toast Notification', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');

    // Mock service worker to simulate background sync
    await page.addInitScript(() => {
      if ('serviceWorker' in navigator) {
        navigator.serviceWorker.ready.then((registration) => {
          // Setup mock for background sync
          if ('sync' in registration) {
            (registration as any).sync = {
              register: async (tag: string) => {
                // Simulate sync completion after a delay
                setTimeout(() => {
                  const event = new Event('sync');
                  (event as any).tag = tag;
                  window.dispatchEvent(event);
                }, 500);
              }
            };
          }
        });
      }
    });
  });

  test('should display toast notification when background sync completes successfully', async () => {
    // Navigate to a page that triggers background sync
    await page.goto('http://localhost:3000/sync-page');

    // Wait for the page to be ready
    await page.waitForLoadState('networkidle');

    // Trigger background sync by clicking a button
    const syncButton = page.getByRole('button', { name: /sync data/i });
    await expect(syncButton).toBeVisible();
    await syncButton.click();

    // Wait for the toast notification to appear
    const toastNotification = page.getByRole('status', { name: /sync completed/i });
    await expect(toastNotification).toBeVisible({ timeout: 5000 });

    // Verify toast content
    await expect(toastNotification).toContainText('Background sync completed successfully');

    // Verify toast has proper accessibility attributes
    const toast = page.locator('[role="status"]').first();
    await expect(toast).toHaveAttribute('aria-live', 'polite');
  });

  test('should display error toast notification when background sync fails', async () => {
    // Navigate to a page that will trigger a failed sync
    await page.goto('http://localhost:3000/sync-page?fail=true');

    // Wait for the page to be ready
    await page.waitForLoadState('networkidle');

    // Mock network error for sync request
    await page.route('**/api/sync', route => {
      route.abort('failed');
    });

    // Trigger background sync
    const syncButton = page.getByRole('button', { name: /sync data/i });
    await syncButton.click();

    // Wait for error toast notification
    const errorToast = page.getByRole('status', { name: /sync failed/i });
    await expect(errorToast).toBeVisible({ timeout: 5000 });

    // Verify error toast content
    await expect(errorToast).toContainText('Background sync failed');

    // Verify error toast has error styling
    const errorElement = page.locator('[role="status"][data-type="error"]').first();
    await expect(errorElement).toHaveClass(/error/);
  });

  test('should auto-dismiss toast notification after specified duration', async () => {
    await page.goto('http://localhost:3000/sync-page');
    await page.waitForLoadState('networkidle');

    // Trigger background sync
    const syncButton = page.getByRole('button', { name: /sync data/i });
    await syncButton.click();

    // Wait for toast to appear
    const toastNotification = page.getByRole('status', { name: /sync completed/i });
    await expect(toastNotification).toBeVisible({ timeout: 5000 });

    // Wait for toast to auto-dismiss (default 5 seconds)
    await expect(toastNotification).toBeHidden({ timeout: 6000 });
  });

  test('should allow manual dismissal of toast notification', async () => {
    await page.goto('http://localhost:3000/sync-page');
    await page.waitForLoadState('networkidle');

    // Trigger background sync
    const syncButton = page.getByRole('button', { name: /sync data/i });
    await syncButton.click();

    // Wait for toast to appear
    const toastNotification = page.getByRole('status', { name: /sync completed/i });
    await expect(toastNotification).toBeVisible({ timeout: 5000 });

    // Find and click the close button
    const closeButton = page.getByRole('button', { name: /close/i }).first();
    await closeButton.click();

    // Verify toast is dismissed
    await expect(toastNotification).toBeHidden();
  });

  test('should display multiple toast notifications for concurrent sync operations', async () => {
    await page.goto('http://localhost:3000/sync-page');
    await page.waitForLoadState('networkidle');

    // Trigger multiple background sync operations
    const syncButton = page.getByRole('button', { name: /sync data/i });
    await syncButton.click();
    await page.waitForTimeout(100);
    await syncButton.click();

    // Wait for multiple toast notifications
    const toastNotifications = page.getByRole('status', { name: /sync completed/i });
    await expect(toastNotifications).toHaveCount(2, { timeout: 5000 });

    // Verify all toasts are visible
    const allToasts = await toastNotifications.all();
    for (const toast of allToasts) {
      await expect(toast).toBeVisible();
    }
  });

  test('should include sync metadata in toast notification', async () => {
    await page.goto('http://localhost:3000/sync-page');
    await page.waitForLoadState('networkidle');

    // Trigger background sync
    const syncButton = page.getByRole('button', { name: /sync data/i });
    await syncButton.click();

    // Wait for toast notification
    const toastNotification = page.getByRole('status', { name: /sync completed/i });
    await expect(toastNotification).toBeVisible({ timeout: 5000 });

    // Verify toast contains sync metadata
    const syncDetails = page.getByText(/synced \d+ items/i);
    await expect(syncDetails).toBeVisible();

    // Verify timestamp is displayed
    const timestamp = page.getByText(/completed at/i);
    await expect(timestamp).toBeVisible();
  });
});
